# -*- coding: utf-8 -*-
import re
from collections import Counter, defaultdict

path = r"C:\Users\26293\Desktop\小车设计\R3圆形两轮差速小车底盘-3D模型.stp"
data = open(path, "rb").read().decode("gbk", errors="replace")

# NAUO 原始行（看格式）
for m in re.finditer(r"#\d+\s*=\s*NEXT_ASSEMBLY_USAGE_OCCURRENCE[^;]*;", data):
    print(m.group(0)[:300])

print("\n--- PRODUCT_DEFINITION 映射 ---")
# PRODUCT id -> name
prod = {}
for m in re.finditer(r"#(\d+)=PRODUCT\('([^']*)'", data):
    prod[m.group(1)] = m.group(2)
# PDF: formation -> product
pdf = {}
for m in re.finditer(r"#(\d+)=PRODUCT_DEFINITION_FORMATION[A-Z_]*\('[^']*','[^']*',#(\d+)", data):
    pdf[m.group(1)] = m.group(2)
# PD: definition -> formation
pd = {}
for m in re.finditer(r"#(\d+)=PRODUCT_DEFINITION\('[^']*','[^']*',#(\d+),#\d+\)", data):
    pd[m.group(1)] = m.group(2)

def pdname(pid):
    return prod.get(pdf.get(pd.get(pid, ""), ""), f"?{pid}")

# NAUO 结构: NAUO('id','name','descr',#parent,#child,$)
rel = Counter()
for m in re.finditer(r"NEXT_ASSEMBLY_USAGE_OCCURRENCE\(\s*'[^']*'\s*,\s*'[^']*'\s*,\s*'[^']*'\s*,\s*#(\d+)\s*,\s*#(\d+)", data):
    rel[(pdname(m.group(1)), pdname(m.group(2)))] += 1
print("\n--- 装配结构（父 -> 子 x 数量） ---")
for (p, c), n in rel.items():
    print(f"{p} -> {c} x {n}")

# 顶点包围盒
vp_ids = set(re.findall(r"VERTEX_POINT\('[^']*',#(\d+)\)", data))
print(f"\n顶点数: {len(vp_ids)}")
pts = {}
for m in re.finditer(r"#(\d+)=CARTESIAN_POINT\('[^']*',\(([-0-9.Ee+]+),([-0-9.Ee+]+),([-0-9.Ee+]+)\)\)", data):
    if m.group(1) in vp_ids:
        pts[m.group(1)] = (float(m.group(2)), float(m.group(3)), float(m.group(4)))
xs = [p[0] for p in pts.values()]; ys = [p[1] for p in pts.values()]; zs = [p[2] for p in pts.values()]
print(f"基于顶点的包围盒 (mm):")
print(f"X: {min(xs):.2f} ~ {max(xs):.2f}  (范围 {max(xs)-min(xs):.2f})")
print(f"Y: {min(ys):.2f} ~ {max(ys):.2f}  (范围 {max(ys)-min(ys):.2f})")
print(f"Z: {min(zs):.2f} ~ {max(zs):.2f}  (范围 {max(zs)-min(zs):.2f})")

# 大圆柱面（>=5mm 半径，找底板外径/轮径）
cyls = Counter()
for m in re.finditer(r"CYLINDRICAL_SURFACE\('[^']*',#\d+,([0-9.Ee+-]+)\)", data):
    r = float(m.group(1))
    if r >= 5:
        cyls[round(r,2)] += 1
print("\n大半径圆柱面 (>=5mm):")
for r, n in sorted(cyls.items()):
    print(f"半径 {r} mm: {n} 个面")

# 圆的半径（CIRCLE），找螺孔和外形圆
circ = Counter()
for m in re.finditer(r"CIRCLE\('[^']*',#\d+,([0-9.Ee+-]+)\)", data):
    circ[round(float(m.group(1)),2)] += 1
print("\n圆弧半径分布（前25）:")
for r, n in circ.most_common(25):
    print(f"半径 {r} mm: {n}")

